begin;
select plan(23);
select has_function('concierge','review_validate_source_location_v1',array['jsonb'],'exact original locator validator');
select has_function('concierge','review_guidance_original_source_locations',array['uuid','jsonb'],'complete original relation before canonicalization');
select has_function('concierge','review_legacy_reply_fence',array['uuid'],'shared typed reply representability fence');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and p.proname in ('review_validate_source_location_v1','review_guidance_original_source_locations','review_legacy_reply_fence') and (has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute') or has_function_privilege('service_role',p.oid,'execute'))),0,'new helpers confer no raw execute right');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='concierge' and p.proname in ('review_validate_source_location_v1','review_guidance_original_source_locations','review_legacy_reply_fence') and (p.prosecdef or not coalesce(p.proconfig @> array['search_path=""'],false))),0,'invoker helpers and empty search paths');
select is((select count(*)::integer from jsonb_object_keys(concierge.review_command_fields())),15,'Review15 unchanged');
select is((select count(*)::integer from jsonb_object_keys(concierge.guidance_command_fields())),9,'Guidance9 unchanged');
select is((select count(*)::integer from jsonb_object_keys(concierge.plan_command_fields())),26,'Plan26 unchanged');
select is((select count(*)::integer from jsonb_object_keys(concierge.care_command_fields())),13,'Care13 unchanged');
select lives_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"whole"}}')$$,'whole locator valid');
select lives_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"page","page":1}}')$$,'page locator valid');
select lives_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":0,"end":1}}')$$,'strict positive text range valid');
select lives_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"time","startMs":0,"endMs":1}}')$$,'strict positive time range valid');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":8,"end":4}}')$$,'P0001','concierge_invalid_input','reversed text rejects');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"text","start":8,"end":8}}')$$,'P0001','concierge_invalid_input','equal text rejects');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"time","startMs":8,"endMs":4}}')$$,'P0001','concierge_invalid_input','reversed time rejects');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"time","startMs":8,"endMs":8}}')$$,'P0001','concierge_invalid_input','equal time rejects');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"TEXT","start":0,"end":1}}')$$,'P0001','concierge_invalid_input','case is not silently coerced');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"whole","extra":"PRIVATE"}}')$$,'P0001','concierge_invalid_input','unknown locator key rejects');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":0,"locator":{"kind":"whole"}}')$$,'P0001','concierge_invalid_input','nonpositive source version rejects');
select throws_ok($$select concierge.review_validate_source_location_v1('{"sourceId":"10000000-0000-4000-8000-000000000001","sourceVersion":1,"locator":{"kind":"page","page":0}}')$$,'P0001','concierge_invalid_input','nonpositive page rejects');
select ok(concierge.review_guidance_issues('10000000-0000-4000-8000-000000000001','{"kind":"review","publication":{"version":1,"documentSchemaVersion":3},"clientReport":"reported","conclusion":"no change","rationale":"reviewed","nextStep":"contact","changes":[" \t"]}','{}','{}',true) @> '[{"path":"body","code":"required"}]','provided blank change is incomplete at required stage');
select ok(not (concierge.review_guidance_issues('10000000-0000-4000-8000-000000000001','{"kind":"review","publication":{"version":1,"documentSchemaVersion":3},"clientReport":"reported","conclusion":"no change","rationale":"reviewed","nextStep":"contact","changes":[]}','{}','{}',true) @> '[{"path":"body","code":"required"}]'),'actual no-change empty list remains valid');
select * from finish();
rollback;
